import { loadFont } from "@remotion/google-fonts/Sora";
import { loadFont as loadMont } from "@remotion/google-fonts/Montserrat";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// CAR & DATA BRASIL v3 (cliente "jose"): retorno do cliente sobre a v2: carro mais bem desenhado, menos verde-água (mais
// clean: fundos branco/verde-escuro, destaques em verde-escuro), sem preço de concorrente, voz Roger em tom comercial
// (src/voz-v3.mp3; tempos abaixo são dessa voz).
// v2: "use mais o site para fazer as animações". Mesma voz da v1; nas cenas da solução
// entram os prints reais do site (início com o campo da placa digitado e clicado, grade do relatório com câmera indo de
// cartão em cartão, "Para quem é" no cartão Pessoa Física, a página inteira sobrevoada no fim).
// v1: Motion: não veio foto nem vídeo, só o site caredatabrasil.com.br.
// Identidade do site: verde floresta (#0A3D2E / #061E14), verde-água do escudo (#26DDB8), verde do botão (#18A658),
// letra Sora nos títulos e Montserrat 900 no logo; escudo com check. Tom sério e confiável, de tecnologia: molas sem
// passar do ponto, câmera em aproximação reta, nada balançando.
// Fio: a placa Mercosul (pergunta → consulta → relatório → preço → botão final).
// Problema (carro usado, contrato) em desenho genérico; o produto (relatório) só entra depois da marca.
// Tempos = tempos da locução src/voz-v1.mp3 (t = 0 no começo da voz; o vídeo tem LEAD de entrada).

const { fontFamily: F } = loadFont("normal", { weights: ["600", "700", "800"], subsets: ["latin", "latin-ext"] });
const { fontFamily: FM } = loadMont("normal", { weights: ["900"], subsets: ["latin"] });

export const CD3_FPS = 30;
const LEAD = 0.25;
export const CD3_FRAMES = Math.round(34.4 * CD3_FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const SOFTBACK = Easing.out(Easing.back(0.9));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: SOFTBACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const bump = (t: number, a: number, d = 0.4) => (t < a || t > a + d ? 0 : Math.sin(((t - a) / d) * Math.PI) * (1 - (t - a) / d));

const DEEP = "#061E14";
const FOREST = "#0A3D2E";
const MINT = "#26DDB8";
const GREEN = "#18A658";
const LIGHT = "#EEF5F1";
const LINE = "#D0E8DA";
const INK = "#0B2A1F";
const SOFT = "#8AA597";
const RED = "#DC2626";
