const T2 = 2.6, T3 = 6.1, T4 = 9.15, T5 = 17.45, T7 = 22.2, T8 = 29.75;

// ───────── texto pela máscara: nasce de baixo de uma linha invisível e fica parado ─────────
type L = [string, number, boolean?];
const Lines: React.FC<{ t: number; items: L[]; size: number; top: number; color?: string; out?: number; pillBg?: string; pillText?: string; weight?: number }> = ({ t, items, size, top, color = WHITE, out, pillBg = FOREST, pillText = WHITE, weight = 800 }) => {
  const o = out === undefined ? 0 : lin(t, out, out + 0.16);
  if (o >= 1) return null;
  return (
    <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap: size * 0.08, opacity: 1 - o, filter: o > 0 ? `blur(${(o * 10).toFixed(1)}px)` : undefined }}>
      {items.map(([w, at, hl], i) => {
        const e = k(t, at, 0.5);
        return (
          <div key={i} style={{ overflow: "hidden", padding: `0 ${size * 0.1}px ${size * 0.08}px`, ...(hl ? { transform: `scale(${(0.9 + 0.1 * pop(t, at, 0.5)).toFixed(4)})` } : {}) }}>
            <div style={{ fontFamily: F, fontWeight: weight, fontSize: size, lineHeight: 1.12, letterSpacing: "-0.04em", whiteSpace: "nowrap", color: hl ? pillText : color, transform: `translateY(${((1 - e) * 112).toFixed(2)}%)`, ...(hl ? { background: pillBg, padding: `${size * 0.03}px ${size * 0.26}px ${size * 0.1}px`, borderRadius: size * 0.24 } : {}) }}>
              {w}
            </div>
          </div>
        );
      })}
    </div>
  );
};
const Cam: React.FC<{ t: number; a: number; b: number; s0?: number; s1?: number; y?: number; children: React.ReactNode }> = ({ t, a, b, s0 = 1, s1 = 1.05, y = 0, children }) => {
  const p = lin(t, a - 0.4, b + 0.4);
  return <AbsoluteFill style={{ transform: `translateY(${(y * p).toFixed(1)}px) scale(${(s0 + (s1 - s0) * p).toFixed(4)})` }}>{children}</AbsoluteFill>;
};
const Glow: React.FC<{ y?: number; a?: number; c?: string }> = ({ y = 50, a = 0.2, c = "38,221,184" }) => (
