// ───────── telas reais do site (prints de caredatabrasil.com.br, em coordenadas de 1x) ─────────
type Key = [number, number, number, number]; // [quando chega, foco x, foco y, zoom]
const camAt = (t: number, keys: Key[]) => {
  let [, x, y, z] = keys[0];
  for (let i = 1; i < keys.length; i++) {
    const [at, kx, ky, kz] = keys[i];
    const p = io(t, at - 0.5, at + 0.05);
    x += (kx - x) * p; y += (ky - y) * p; z += (kz - z) * p;
  }
  return { x, y, z };
};
// a tela inteira, posta para que o ponto (fx, fy) caia em (cx, cy) com zoom z
