// as cenas num tempo t da locução da v3 (a v4 usa as mesmas cenas com a voz nova, convertendo o tempo)
export const CarDataScenes: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill style={{ background: FOREST }}>
    {SCENES.map(([at, S, clip], i) => {
      const end = i + 1 < SCENES.length ? SCENES[i + 1][0] + 0.45 : 1e9;
      if (t < at || t >= end) return null;
      const p = i === 0 ? 1 : interpolate(t, [at, at + 0.42], [0, 1], { ...cl, easing: INOUT });
      return (
        <AbsoluteFill key={i} style={p < 1 ? { clipPath: clip(p) } : undefined}>
          <S t={t} />
        </AbsoluteFill>
      );
    })}
  </AbsoluteFill>
);

